UPDATE `USER`
   SET IS_DELETED = FALSE,
       DELETED_AT = NULL,
       LOGIN_SESSION_ID = NULL,
       NICKNAME = #{nickname}

       ,EMAIL = #{email}

 WHERE ID = #{memberId}
   AND IS_DELETED = TRUE

UPDATE `USER`
   SET LOGIN_SESSION_ID = #{loginSessionId}
 WHERE ID = #{memberId}
   AND IS_DELETED = FALSE

UPDATE `USER`
   SET LOGIN_SESSION_ID = NULL
 WHERE ID = #{memberId}
   AND LOGIN_SESSION_ID = #{loginSessionId}

mapper.select:
SELECT COUNT(*)
  FROM `USER`
 WHERE ID = #{memberId}
   AND LOGIN_SESSION_ID = #{loginSessionId}
   AND IS_DELETED = FALSE

SELECT FOLLOWER_MEMBER.USER_ID AS FOLLOWER_USER_ID ,FOLLOWER_MEMBER.NICKNAME AS FOLLOWER_NICKNAME ,FOLLOWED_MEMBER.USER_ID AS FOLLOWING_USER_ID ,FOLLOWED_MEMBER.NICKNAME AS FOLLOWING_NICKNAME FROM FOLLOWE F JOIN `USER` FOLLOWER_MEMBER ON FOLLOWER_MEMBER.ID = F.FOLLOWER_ID JOIN `USER` FOLLOWED_MEMBER ON FOLLOWED_MEMBER.ID = F.FOLLOWERING_ID
(FOLLOWER_MEMBER.USER_ID LIKE CONCAT('%', #{keyword}, '%') OR FOLLOWER_MEMBER.NICKNAME LIKE CONCAT('%', #{keyword}, '%') OR FOLLOWED_MEMBER.USER_ID LIKE CONCAT('%', #{keyword}, '%') OR FOLLOWED_MEMBER.NICKNAME LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY F.FOLLOWER_ID DESC, F.FOLLOWERING_ID DESC LIMIT #{size} OFFSET #{offset}
